/** @type {import('tailwindcss').Config} */

// Palette shades resolve to CSS variables (src/styles/tw-palette.css, generated by
// scripts/gen-tw-palette.mjs). Light values = default Tailwind, so public pages
// are unchanged; [data-theme="dark"] remaps them for the CRM.
// Backgrounds/borders (--twc-*) and text (--twt-*) are separate palettes: a
// saturated button background and readable text on near-black need different shades.

const HUES = ['gray', 'indigo', 'green', 'red', 'blue', 'yellow', 'orange', 'amber', 'teal', 'purple', 'lime', 'emerald', 'rose', 'pink', 'sky', 'violet'];
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];

const cssVar = (name) => `rgb(var(${name}) / <alpha-value>)`;
const palette = (prefix) => Object.fromEntries(
  HUES.map((hue) => [hue, Object.fromEntries(SHADES.map((s) => [s, cssVar(`--${prefix}-${hue}-${s}`)]))])
);

export default {
  content: ['./index.html', './src/**/*.{js,jsx}'],
  theme: {
    extend: {
      colors: {
        ...palette('twc'),
        surface: cssVar('--twc-surface'), // use bg-surface, never bg-white, for panels
      },
      textColor: palette('twt'),
    },
  },
  plugins: [],
}
